// STD-016 · generated from the card contract · non-normative
let p_start = datetime(2026-06-01);
let p_end   = datetime(2026-07-01);
let scope        = "prod";
findings
| where severity == "critical" and internet_facing
| where due_at >= p_start and due_at < p_end
| where scope_id == scope
| summarize due = count(),
            within_sla = countif(remediated_at <= due_at
                                 and validation_status == "validated")
| extend sla_compliance_pct = iff(due == 0, real(null),
                                  round(100.0 * within_sla / due, 1))
